/**
 * Mr OneHook Pro: what the Pro screen shows, derived from `GET /api/member/mr-onehook-pro`
 * (`MrOneHookProStatus`, generated by `onehook-mr-onehook-client`) and two fields of the member's State
 * (`membershipEndsAt`, `pendingSubscriptionTier`).
 *
 * Plans: Free (10 messages a day, 1 saved chat, no files) and Pro (a Pro subscription, or a membership
 * tier that includes Pro). The server decides the plan; this module only turns its answer into screen
 * copy, so it stays pure and unit-tested. Network calls live in `store/mr-onehook-pro-store.ts`.
 */
import {
  MrOneHookPlan,
  MrOneHookProSource,
  ProBillingPeriod,
  ProRefundStatus,
  ProSubscriptionStatus,
  type MrOneHookPlanLimits,
  type MrOneHookProStatus,
  type ProNotice,
  type ProOffer,
  type ProSubscription,
} from 'onehook-mr-onehook-client';
import { formatInr } from '../config/membership.config';

/**
 * Limits to assume before the Pro status has loaded (or while Pro is off). They mirror the server's
 * Free plan so nothing is offered that the server would refuse; the server's `limits` replace them.
 */
export const FREE_PLAN_FALLBACK_LIMITS: MrOneHookPlanLimits = {
  dailyMessages: 10,
  maxSessions: 1,
  attachmentsAllowed: false,
  maxAttachmentBytes: 5 * 1024 * 1024,
  maxAttachmentsPerMessage: 3,
};

export interface MrOneHookPlanContext {
  plan: MrOneHookPlan;
  limits: MrOneHookPlanLimits;
  /** Pro entry points (the Pro screen, the attach button, "Ask Mr OneHook") are shown. */
  proVisible: boolean;
}

/**
 * The plan the chat should assume. Until the status is read (or when Pro is off) it is Free with
 * {@link FREE_PLAN_FALLBACK_LIMITS}, and no Pro entry point shows.
 */
export function mrOneHookPlanContext(
  status: MrOneHookProStatus | null,
  availability: 'unknown' | 'loading' | 'ready' | 'off' | 'error'
): MrOneHookPlanContext {
  if (availability === 'ready' && status) {
    return { plan: status.plan, limits: status.limits, proVisible: true };
  }
  return { plan: MrOneHookPlan.FREE, limits: FREE_PLAN_FALLBACK_LIMITS, proVisible: false };
}

export function isProPlan(plan: MrOneHookPlan | undefined): boolean {
  return plan === MrOneHookPlan.PRO;
}

/** Formats a minor-unit (paise) INR amount with the site's INR helper, e.g. 79900 -> "₹799". */
export function formatMinorInr(amountMinor: number): string {
  const rupees = amountMinor / 100;
  return formatInr(Number.isInteger(rupees) ? rupees : Number(rupees.toFixed(2)));
}

/** "12 Mar 2026" in the reader's locale, from an ISO-8601 string or epoch seconds. */
export function formatProDate(value: string | number | undefined, locale?: string): string {
  if (value === undefined || value === '') return '';
  const ms = typeof value === 'number' ? value * 1000 : Date.parse(value);
  if (!Number.isFinite(ms)) return '';
  return new Date(ms).toLocaleDateString(locale, {
    day: 'numeric',
    month: 'short',
    year: 'numeric',
  });
}

export function periodLabel(period: ProBillingPeriod): string {
  return period === ProBillingPeriod.YEARLY ? 'year' : 'month';
}

export interface OfferView {
  billingPeriod: ProBillingPeriod;
  /** "₹799/month" */
  priceLabel: string;
}

export function offerViews(offers: readonly ProOffer[]): OfferView[] {
  const order = [ProBillingPeriod.MONTHLY, ProBillingPeriod.YEARLY] as string[];
  return [...offers]
    .sort((a, b) => order.indexOf(a.billingPeriod) - order.indexOf(b.billingPeriod))
    .map((o) => ({
      billingPeriod: o.billingPeriod,
      priceLabel: `${formatMinorInr(o.priceMinor)}/${periodLabel(o.billingPeriod)}`,
    }));
}

export interface SubscriptionView {
  status: ProSubscriptionStatus;
  statusLabel: string;
  /** "Pro until 12 Mar 2026" */
  periodLine?: string;
  /** "Next charge 12 Mar 2026: ₹799" */
  nextChargeLine?: string;
  autoRenew: boolean;
  /** The auto-renew switch is offered (a running, unpaused subscription). */
  canToggleAutoRenew: boolean;
  /** Why nothing renews while the membership covers Pro. */
  pausedLine?: string;
  /** Refund status, amount and date. */
  refundLine?: string;
}

export interface ScheduledView {
  /** "Starts 12 Mar 2026, first charge then: ₹799/month" */
  line: string;
  startsAt: string;
}

export interface KeepProView {
  /** "Keep Mr OneHook Pro after 12 Mar 2026" */
  title: string;
  endsAtLabel: string;
  offers: OfferView[];
}

export interface NoticeView {
  noticeId: string;
  text: string;
}

export type ProHeadline = 'FREE' | 'SUBSCRIPTION' | 'MEMBERSHIP' | 'COMPLIMENTARY';

export interface ProScreenModel {
  plan: MrOneHookPlan;
  headline: ProHeadline;
  /** One-line summary under the title. */
  summary: string;
  /** State is waiting for the Pro handover after an upgrade: show "Activating your membership". */
  activating: boolean;
  /** Buy buttons are shown (Free with `canPurchase`). */
  canBuy: boolean;
  offers: OfferView[];
  subscription?: SubscriptionView;
  /** "Keep Mr OneHook Pro after <date>" (membership includes Pro and is set to end; nothing kept yet). */
  keepPro?: KeepProView;
  /** A kept plan waiting for its first charge; it can be withdrawn. */
  scheduled?: ScheduledView;
  notices: NoticeView[];
  usage?: { usedPercent: number; warning: boolean; line: string };
}

export interface ProMembershipContext {
  /** State `membershipEndsAt` (epoch seconds). */
  membershipEndsAt?: number;
  /** State `pendingSubscriptionTier` is set. */
  pendingUpgrade?: boolean;
  /** Display name of the member's tier, e.g. for "Included with your Infinity membership". */
  tierName?: string;
}

const ENDED_REASON_COPY: Readonly<Record<string, string>> = {
  CANCELLED: 'Ended: auto-renew was off',
  PAYMENT_FAILED: 'Ended: the renewal payment failed',
  INCLUDED_IN_MEMBERSHIP: 'Ended: your membership includes Mr OneHook Pro',
  CONTINUATION_WITHDRAWN: 'Ended: the kept plan was withdrawn',
  REFUNDED: 'Ended: the unused months were refunded',
  PAYMENT_DECLINED: 'Ended: the payment was declined',
};

function statusLabel(sub: ProSubscription): string {
  switch (sub.status) {
    case ProSubscriptionStatus.ACTIVE:
      return sub.pausedForMembership
        ? 'Paused for your membership'
        : sub.autoRenew
          ? 'Active'
          : 'Active, not renewing';
    case ProSubscriptionStatus.GRACE:
      return 'Payment issue: we’ll retry the charge';
    case ProSubscriptionStatus.PENDING:
      return 'Payment processing';
    case ProSubscriptionStatus.SCHEDULED:
      return 'Scheduled';
    default:
      return (sub.endedReason && ENDED_REASON_COPY[sub.endedReason]) || 'Ended';
  }
}

function refundLine(sub: ProSubscription, locale?: string): string | undefined {
  const refund = sub.refund;
  if (!refund) return undefined;
  const amount = formatMinorInr(refund.amountMinor);
  switch (refund.status) {
    case ProRefundStatus.SCHEDULED:
      return `Refund of ${amount} scheduled for ${formatProDate(refund.dueAt, locale)}`;
    case ProRefundStatus.ISSUED:
      return `Refunded ${amount} on ${formatProDate(refund.issuedAt ?? refund.dueAt, locale)}`;
    case ProRefundStatus.CANCELLED:
      return 'Refund cancelled: your yearly plan continues';
    default:
      return undefined;
  }
}

function subscriptionView(sub: ProSubscription, locale?: string): SubscriptionView {
  const running =
    sub.status === ProSubscriptionStatus.ACTIVE || sub.status === ProSubscriptionStatus.GRACE;
  const price = `${formatMinorInr(sub.priceMinor)}/${periodLabel(sub.billingPeriod)}`;
  const view: SubscriptionView = {
    status: sub.status,
    statusLabel: statusLabel(sub),
    autoRenew: sub.autoRenew,
    canToggleAutoRenew: running && !sub.pausedForMembership,
  };
  if (sub.currentPeriodEnd && sub.status !== ProSubscriptionStatus.ENDED) {
    view.periodLine = `Pro until ${formatProDate(sub.currentPeriodEnd, locale)}`;
  }
  if (sub.nextChargeAt) {
    view.nextChargeLine = `Next charge ${formatProDate(sub.nextChargeAt, locale)}: ${price}`;
  }
  if (sub.pausedForMembership) {
    view.pausedLine =
      'Your membership includes Mr OneHook Pro now, so this subscription doesn’t renew. You keep the time you already paid for.';
  }
  const refund = refundLine(sub, locale);
  if (refund) view.refundLine = refund;
  return view;
}

/** Copy for one notice (refunds, renewals, kept plans, the attachment allowance). */
export function noticeText(notice: ProNotice, locale?: string): string {
  const amount = typeof notice.amountMinor === 'number' ? formatMinorInr(notice.amountMinor) : '';
  const at = formatProDate(notice.at, locale);
  switch (notice.kind) {
    case 'PRO_PURCHASED':
      return 'Welcome to Mr OneHook Pro.';
    case 'PRO_RENEWED':
      return amount ? `Mr OneHook Pro renewed: ${amount}.` : 'Mr OneHook Pro renewed.';
    case 'PRO_RENEWAL_FAILED':
      return 'Your Mr OneHook Pro renewal payment failed. We’ll retry it for a few days.';
    case 'PRO_ENDED':
      return at ? `Mr OneHook Pro ended on ${at}.` : 'Mr OneHook Pro ended.';
    case 'PRO_PAUSED_FOR_MEMBERSHIP':
      return 'Your membership includes Mr OneHook Pro, so your subscription stopped renewing.';
    case 'PRO_REFUND_SCHEDULED':
      return `A refund of ${amount || 'your unused months'} is scheduled${at ? ` for ${at}` : ''}.`;
    case 'PRO_REFUND_ISSUED':
      return `We refunded ${amount || 'your unused months'}${at ? ` on ${at}` : ''}.`;
    case 'PRO_REFUND_CANCELLED':
      return 'Your refund was cancelled because your membership ended. Your yearly plan continues.';
    case 'PRO_RESUMED':
      return 'Your Mr OneHook Pro subscription resumed.';
    case 'PRO_CONTINUATION_SCHEDULED':
      return at
        ? `Mr OneHook Pro is kept after your membership. First charge on ${at}.`
        : 'Mr OneHook Pro is kept after your membership.';
    case 'PRO_CONTINUATION_CANCELLED':
      return 'Your kept Mr OneHook Pro plan was cancelled. Nothing was charged.';
    case 'PRO_CONTINUATION_STARTED':
      return amount
        ? `Your kept Mr OneHook Pro plan started: ${amount}.`
        : 'Your kept Mr OneHook Pro plan started.';
    case 'ATTACHMENT_USAGE_WARNING':
      return 'You have used most of this month’s file processing.';
    default:
      return 'There is an update about your Mr OneHook Pro plan.';
  }
}

/** Builds everything the Pro screen shows. Pure. */
export function buildProScreenModel(
  status: MrOneHookProStatus,
  membership: ProMembershipContext = {},
  locale?: string
): ProScreenModel {
  const sub = status.subscription;
  const offers = offerViews(status.offers);
  const scheduledSub = sub?.status === ProSubscriptionStatus.SCHEDULED ? sub : undefined;

  let headline: ProHeadline;
  let summary: string;
  switch (status.source) {
    case MrOneHookProSource.MEMBERSHIP:
      headline = 'MEMBERSHIP';
      summary = membership.tierName
        ? `Included with your ${membership.tierName} membership`
        : 'Included with your membership';
      break;
    case MrOneHookProSource.COMPLIMENTARY:
      headline = 'COMPLIMENTARY';
      summary = scheduledSub?.scheduledStartAt
        ? `Free until ${formatProDate(scheduledSub.scheduledStartAt, locale)}`
        : 'Free for now';
      break;
    case MrOneHookProSource.SUBSCRIPTION:
      headline = 'SUBSCRIPTION';
      summary = 'You have Mr OneHook Pro';
      break;
    default:
      headline = status.plan === MrOneHookPlan.PRO ? 'SUBSCRIPTION' : 'FREE';
      summary =
        status.plan === MrOneHookPlan.PRO
          ? 'You have Mr OneHook Pro'
          : 'Unlimited messages, 3 saved chats and files with Mr OneHook Pro';
  }

  const model: ProScreenModel = {
    plan: status.plan,
    headline,
    summary,
    activating: Boolean(membership.pendingUpgrade),
    canBuy: headline === 'FREE' && status.canPurchase && !membership.pendingUpgrade,
    offers,
    notices: status.notices.map((n) => ({ noticeId: n.noticeId, text: noticeText(n, locale) })),
  };

  if (sub && !scheduledSub && headline !== 'MEMBERSHIP')
    model.subscription = subscriptionView(sub, locale);
  // A subscription paused for (or ended by) the membership still has refund news worth showing.
  if (
    sub &&
    !scheduledSub &&
    headline === 'MEMBERSHIP' &&
    (sub.pausedForMembership || sub.refund)
  ) {
    model.subscription = subscriptionView(sub, locale);
  }

  if (scheduledSub?.scheduledStartAt) {
    const price = `${formatMinorInr(scheduledSub.priceMinor)}/${periodLabel(scheduledSub.billingPeriod)}`;
    model.scheduled = {
      startsAt: scheduledSub.scheduledStartAt,
      line: `Starts ${formatProDate(scheduledSub.scheduledStartAt, locale)}, first charge then: ${price}`,
    };
  } else if (headline === 'MEMBERSHIP' && membership.membershipEndsAt) {
    const endsAtLabel = formatProDate(membership.membershipEndsAt, locale);
    model.keepPro = { title: `Keep Mr OneHook Pro after ${endsAtLabel}`, endsAtLabel, offers };
  }

  if (status.attachmentUsage) {
    const u = status.attachmentUsage;
    model.usage = {
      usedPercent: u.usedPercent,
      warning: u.warning,
      line: `${u.usedPercent}% of this month’s file processing used. Resets ${formatProDate(u.resetsAt, locale)}.`,
    };
  }
  return model;
}
